class Solution:
    def findDiagonalOrder(self, mat: list[list[int]]) -> list[int]:
        if not mat:
            return []
        m, n = len(mat), len(mat[0])
        diags = [[] for _ in range(m + n - 1)]
        for i in range(m):
            for j in range(n):
                diags[i + j].append(mat[i][j])
        result = []
        for d in range(len(diags)):
            if d % 2 == 0:
                result.extend(diags[d][::-1])
            else:
                result.extend(diags[d])
        return result

